function mergeDashboardPayload(current, payload) {
  const next = { ...current, ...payload };
  const nestedMergeKeys = ["optionBot", "scanJob", "oiScannerAuto", "scannerAuto", "scheduler", "dashboardSummary", "learning"];
  nestedMergeKeys.forEach((key) => {
    if (payload?.[key] && current?.[key]) next[key] = { ...current[key], ...payload[key] };
  });
  const preserveKeys = [
    "scannerHistory",
    "scannerHistoryDays",
    "oiScanResults",
    "oiMag7ScanResults",
    "oiMag7LastNonEmptyResults",
    "oiWatchlistScanResults",
    "oiWatchlistLastNonEmptyResults",
    "scanResults",
    "candidateResults",
    "mag7ScanResults",
    "mag7CandidateResults",
  ];
  preserveKeys.forEach((key) => {
    const incoming = payload?.[key];
    const existing = current?.[key];
    if (Array.isArray(existing) && existing.length && Array.isArray(incoming) && incoming.length === 0) {
      next[key] = existing;
    }
  });
  if (payload?.status?.marketStatus === "Loading" && current?.status) {
    next.status = { ...current.status, ...payload.status };
    if (!payload.status.clockTime && current.status.clockTime) next.status.clockTime = current.status.clockTime;
    if (!payload.status.lastRefresh && current.status.lastRefresh) next.status.lastRefresh = current.status.lastRefresh;
  }
  return next;
}

function isWithinOiExpiryWindow(row, maxDte = OI_SCANNER_MAX_DTE) {
  const days = Number(row?.days_to_expiration);
  return Number.isFinite(days) && days > 0 && days <= maxDte;
}

function expandStockSetupMatches(row) {
  const rawSetup = String(row?.stock_setup_name || row?.setup_name || "").trim();
  if (!rawSetup) return [];
  if (!rawSetup.startsWith("EMA + VWAP")) return [rawSetup];
  const matches = ["EMA + VWAP"];
  if (rawSetup !== "EMA + VWAP") matches.push(rawSetup);
  return STOCK_SETUP_DISPLAY_ORDER.filter((label) => matches.includes(label));
}

function renderStockSetupMatches(row) {
  const matches = expandStockSetupMatches(row);
  if (!matches.length) return "--";
  return (
    <div className="oi-why-badges">
      {matches.map((label) => (
        <span className="oi-why-badge oi-why-setup" key={label}>{label}</span>
      ))}
    </div>
  );
}

