function renderCloudAction(value) {
  const action = String(value || "CLOUD DATA UNAVAILABLE").toUpperCase();
  const tone = action.startsWith("TRADE") ? "trade" : action.startsWith("WAIT") ? "wait" : "block";
  return <span className={`cloud-action-chip cloud-action-${tone}`}>{action}</span>;
}

function renderMtfSignalBadges(value, row) {
  const labels = String(value || row?.stock_mtf_bullish_signal_labels || "")
    .split(",")
    .map((label) => label.trim())
    .filter(Boolean);
  if (!labels.length) return "--";
  return (
    <div className="mtf-table-signals">
      {labels.map((entry) => {
        const hasYellow = /yellow/i.test(entry);
        const hasCyan = /cyan/i.test(entry);
        const tone = hasYellow && hasCyan ? "both-colors" : hasYellow ? "yellow" : "cyan";
        const colors = hasYellow && hasCyan ? "yellow + cyan" : hasYellow ? "yellow" : "cyan";
        const label = entry.replace(/\s+(?:yellow(?:\+cyan)?|cyan(?:\+yellow)?)$/i, "");
        return <span className={`mtf-table-signal mtf-table-signal-${tone}`} key={entry}>{label} <small>{colors}</small></span>;
      })}
    </div>
  );
}

